/**
 * BillingRoute — smoke tests.
 *
 * Verifies the page header (title + breadcrumb) and the ComingSoon
 * placeholder are rendered. BillingRoute has no data fetching or
 * interactive state — every line executes on initial render.
 */

import { describe, it, expect } from "vitest";
import { render, screen } from "@testing-library/react";
import { MemoryRouter } from "react-router-dom";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { BillingRoute } from "../../src/routes/BillingRoute";

// BillingRoute renders ComingSoon which uses data-testid — no stub needed.

function renderRoute(): void {
  render(
    <MemoryRouter>
      <BillingRoute />
    </MemoryRouter>,
  );
}

describe("BillingRoute", () => {
  it("renders the page title as an h1 heading", () => {
    renderRoute();
    // AdminPageHeader renders an <h1>; ComingSoon renders an <h2> with the
    // same title text. Assert on the h1 to avoid ambiguity.
    expect(
      screen.getByRole("heading", { level: 1, name: m.nav_billing() }),
    ).toBeInTheDocument();
  });

  it("renders the breadcrumb containing the billing label", () => {
    renderRoute();
    const breadcrumb = screen.getByLabelText(m.admin_breadcrumb());
    expect(breadcrumb.textContent).toContain(m.nav_billing());
  });

  it("renders the ComingSoon placeholder", () => {
    renderRoute();
    expect(screen.getByTestId("admin-coming-soon")).toBeInTheDocument();
  });

  it("renders the phase label in the ComingSoon card", () => {
    renderRoute();
    const card = screen.getByTestId("admin-coming-soon");
    expect(card.textContent).toContain(m.common_phase({ n: "4" }));
  });
});


