/**
 * ComingSoon — unit tests.
 *
 * Covers:
 *  - Renders the "coming soon" eyebrow badge
 *  - Renders the title passed as a prop
 *  - Renders the phase label when supplied (phase branch)
 *  - Omits the phase label when not supplied (no-phase branch)
 *  - Renders the body copy
 */

import { describe, it, expect } from "vitest";
import { render, screen } from "@testing-library/react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { ComingSoon } from "../../src/routes/ComingSoon";

describe("ComingSoon", () => {
  it("renders the coming-soon badge", () => {
    render(<ComingSoon title="Billing" />);
    expect(screen.getByText(m.tenants_coming_soon())).toBeInTheDocument();
  });

  it("renders the title prop as a heading", () => {
    render(<ComingSoon title="My Surface" />);
    expect(screen.getByRole("heading", { name: "My Surface" })).toBeInTheDocument();
  });

  it("renders the phase label when the phase prop is supplied", () => {
    const phase = m.common_phase({ n: "4" });
    render(<ComingSoon title="Billing" phase={phase} />);
    expect(screen.getByText(new RegExp(phase))).toBeInTheDocument();
  });

  it("does NOT render a phase separator when phase is omitted", () => {
    render(<ComingSoon title="Billing" />);
    // The phase separator is " · "; asserting it is absent when phase is omitted.
    expect(screen.queryByText(/·/)).not.toBeInTheDocument();
  });

  it("renders the body copy (prefix text is present)", () => {
    render(<ComingSoon title="Billing" />);
    // The body <p> contains prefix + suffix as siblings; use a broader query.
    const section = screen.getByTestId("admin-coming-soon");
    expect(section.textContent).toContain(m.tenants_coming_soon_body_prefix());
  });

  it("is a <section> element", () => {
    render(<ComingSoon title="Billing" />);
    // data-testid="admin-coming-soon" is on the <section>; the section role is 'region' with a heading label.
    expect(screen.getByTestId("admin-coming-soon").tagName).toBe("SECTION");
  });
});


