/**
 * MembersRoute — "Invite new user" navigation tests.
 *
 * These tests verify that clicking the "Invite new user" button navigates
 * to /admin/invite?org=<derived-org-id>. The derivation logic is:
 *   - workspace row (parent_id set)  → use parent_id
 *   - org row     (no parent_id)     → use tenant id
 *
 * Kept in tests/routes/ (not tests/members/) so we can own our own
 * module-level mocks without disturbing the existing smoke test in
 * tests/members/MembersRoute.test.tsx.
 */
import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter } from "react-router-dom";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import type { AdminTenant, ListTenantsResult } from "../../src/api/tenants";
import type { ListUsersResult } from "../../src/api/users";

// --- Module mocks (hoisted) ---

const navigate = vi.fn();

vi.mock("react-router-dom", async () => {
  const actual = await vi.importActual<typeof import("react-router-dom")>("react-router-dom");
  return {
    ...actual,
    useNavigate: () => navigate,
  };
});

vi.mock("../../src/api/tenants", () => ({
  listTenants: vi.fn(),
  listWorkspaceMembers: vi.fn().mockResolvedValue({ members: [] }),
  removeWorkspaceMember: vi.fn(),
  updateMembershipRole: vi.fn(),
  addWorkspaceMember: vi.fn(),
  lookupWorkspaceMemberByEmail: vi.fn(),
  deleteTenant: vi.fn(),
  createTenant: vi.fn(),
  getTenant: vi.fn(),
  updateTenant: vi.fn(),
  updateTenantStatus: vi.fn(),
  activateTenant: vi.fn(),
}));

vi.mock("../../src/api/users", () => ({
  listUsers: vi.fn(),
}));

// --- Import after mocks ---

import { MembersRoute } from "../../src/routes/MembersRoute";
import { listTenants, listWorkspaceMembers } from "../../src/api/tenants";
import { listUsers } from "../../src/api/users";

// --- Fixtures ---

/** Minimal valid AdminTenant fixture. */
function makeTenant(
  overrides: Partial<AdminTenant> & Pick<AdminTenant, "id" | "name">,
): AdminTenant {
  return {
    slug: overrides.name.toLowerCase().replace(/\s+/g, "-"),
    created_at: "2026-01-01T00:00:00Z",
    updated_at: "2026-01-01T00:00:00Z",
    status: "active",
    ...overrides,
  };
}

function tenantsResult(tenants: AdminTenant[]): ListTenantsResult {
  return { tenants, next_page_token: "" };
}

const emptyUsers: ListUsersResult = { users: [], next_cursor: "" };

// --- Tests ---

describe("MembersRoute — Invite new user navigation", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.mocked(listUsers).mockResolvedValue(emptyUsers);
  });

  it("navigates to /admin/invite?org=<parent_id> when a workspace (with parent_id) is selected", async () => {
    // The workspace "ws-1" has parent_id "uuid-org-a" — the button must
    // derive the org id from parent_id.
    const workspace = makeTenant({ id: "ws-1", name: "Eng", parent_id: "uuid-org-a" });
    vi.mocked(listTenants).mockResolvedValue(tenantsResult([workspace]));

    render(
      // ?workspace=ws-1 so the route resolves this tenant as selected.
      <MemoryRouter initialEntries={["/admin/members?workspace=ws-1"]}>
        <MembersRoute />
      </MemoryRouter>,
    );

    await screen.findByTestId("members-route-invite-user");
    await userEvent.click(screen.getByTestId("members-route-invite-user"));

    expect(navigate).toHaveBeenCalledWith("/admin/invite?org=uuid-org-a");
  });

  it("navigates to /admin/invite?org=<id> when an organization (no parent_id) is selected", async () => {
    // The org "uuid-org-a" has no parent_id — the button must use the
    // tenant's own id as the org param.
    const org = makeTenant({ id: "uuid-org-a", name: "Acme" });
    vi.mocked(listTenants).mockResolvedValue(tenantsResult([org]));

    render(
      <MemoryRouter initialEntries={["/admin/members?workspace=uuid-org-a"]}>
        <MembersRoute />
      </MemoryRouter>,
    );

    await screen.findByTestId("members-route-invite-user");
    await userEvent.click(screen.getByTestId("members-route-invite-user"));

    expect(navigate).toHaveBeenCalledWith("/admin/invite?org=uuid-org-a");
  });

  it("falls back to /admin/invite (no org) when no workspace is resolved", async () => {
    // No ?workspace param and listTenants returns no tenants: the
    // auto-select effect finds nothing, tenant stays null, so the invite
    // button navigates to the org-less /admin/invite.
    vi.mocked(listTenants).mockResolvedValue(tenantsResult([]));

    render(
      <MemoryRouter initialEntries={["/admin/members"]}>
        <MembersRoute />
      </MemoryRouter>,
    );

    // No tenant resolved → the empty-state prompt renders instead of the panel.
    await screen.findByText(m.members_select_workspace_prompt());
    await userEvent.click(screen.getByTestId("members-route-invite-user"));

    expect(navigate).toHaveBeenCalledWith("/admin/invite");
  });
});

describe("MembersRoute — auto-select first workspace", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.mocked(listUsers).mockResolvedValue(emptyUsers);
  });

  it("selects the first tenant via ?workspace when none is in the URL", async () => {
    const first = makeTenant({ id: "ws-first", name: "First" });
    vi.mocked(listTenants).mockResolvedValue(tenantsResult([first]));

    render(
      <MemoryRouter initialEntries={["/admin/members"]}>
        <MembersRoute />
      </MemoryRouter>,
    );

    // Once auto-selected, the resolve effect renders the panel header for the
    // first tenant ("First") rather than the empty-state prompt.
    expect(await screen.findByText("First")).toBeInTheDocument();
  });
});

describe("MembersRoute — member detail drawer (?user)", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("opens the drawer for the selected user and closes it", async () => {
    const workspace = makeTenant({ id: "ws-1", name: "Eng", parent_id: "org-a" });
    vi.mocked(listTenants).mockResolvedValue(tenantsResult([workspace]));
    vi.mocked(listUsers).mockResolvedValue({
      users: [
        {
          id: "u1",
          email: "alice@x",
          display_name: "Alice",
          status: "active",
          created_at: "2026-01-01T00:00:00Z",
        } as unknown as ListUsersResult["users"][number],
      ],
      next_cursor: "",
    });

    render(
      <MemoryRouter initialEntries={["/admin/members?workspace=ws-1&user=u1"]}>
        <MembersRoute />
      </MemoryRouter>,
    );

    // The drawer surfaces the member's display name once listUsers resolves.
    expect(await screen.findAllByText("Alice")).not.toHaveLength(0);

    const closeBtn = screen.getByRole("button", { name: m.common_close_drawer_aria() });
    await userEvent.click(closeBtn);

    // After close the drawer's dedicated close control is gone.
    await waitFor(() =>
      expect(
        screen.queryByRole("button", { name: m.common_close_drawer_aria() }),
      ).not.toBeInTheDocument(),
    );
  });

  it("renders no drawer when the selected user is not found", async () => {
    const workspace = makeTenant({ id: "ws-1", name: "Eng", parent_id: "org-a" });
    vi.mocked(listTenants).mockResolvedValue(tenantsResult([workspace]));
    vi.mocked(listUsers).mockResolvedValue(emptyUsers);

    render(
      <MemoryRouter initialEntries={["/admin/members?workspace=ws-1&user=ghost"]}>
        <MembersRoute />
      </MemoryRouter>,
    );

    await screen.findByTestId("members-route-invite-user");
    expect(
      screen.queryByRole("button", { name: m.common_close_drawer_aria() }),
    ).not.toBeInTheDocument();
  });
});

describe("MembersRoute — child callback wiring (sidebar + member row)", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.mocked(listUsers).mockResolvedValue(emptyUsers);
  });

  it("selects a workspace from the tree, then opens the drawer for a clicked member", async () => {
    const user = userEvent.setup();
    const ws1 = makeTenant({ id: "ws-1", name: "Eng", parent_id: "org-a" });
    const ws2 = makeTenant({ id: "ws-2", name: "Sales", parent_id: "org-a" });
    vi.mocked(listTenants).mockResolvedValue(tenantsResult([ws1, ws2]));
    // MembersPanel reads its rows via listWorkspaceMembers — return one member
    // so the row's name cell is clickable (drives handleSelectMember).
    vi.mocked(listWorkspaceMembers).mockResolvedValue({
      members: [
        {
          membership_id: "m1",
          user_id: "u1",
          role: "member",
          created_at: "2026-05-10T12:00:00Z",
          display_name: "Alice",
          email: "alice@x",
          workspaces_count: 1,
          two_fa: "enabled",
        },
      ],
    } as unknown as Awaited<ReturnType<typeof listWorkspaceMembers>>);
    // The drawer resolves its member via listUsers.
    vi.mocked(listUsers).mockResolvedValue({
      users: [
        {
          id: "u1",
          email: "alice@x",
          display_name: "Alice",
          status: "active",
          created_at: "2026-05-10T12:00:00Z",
        } as unknown as ListUsersResult["users"][number],
      ],
      next_cursor: "",
    });

    render(
      <MemoryRouter initialEntries={["/admin/members?workspace=ws-1"]}>
        <MembersRoute />
      </MemoryRouter>,
    );

    // Clicking a different workspace row in the tree drives handleSelectWorkspace.
    const ws2Row = await screen.findByTestId("sidebar-row-ws-2");
    await user.click(ws2Row);

    // Switch back to ws-1 so the member panel for ws-1 renders Alice.
    const ws1Row = await screen.findByTestId("sidebar-row-ws-1");
    await user.click(ws1Row);

    // Clicking the member's name cell drives handleSelectMember → ?user=u1 →
    // the detail drawer mounts (its close affordance appears).
    const nameCell = await screen.findByTestId("members-row-u1-name-cell");
    await user.click(nameCell);

    expect(
      await screen.findByRole("button", { name: m.common_close_drawer_aria() }),
    ).toBeInTheDocument();
  });
});


