import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import type { MockInstance } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import { MemoryRouter } from "react-router-dom";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { OrganizationRoute } from "../../src/routes/OrganizationRoute";

const CODE = {
  id: "sc-1",
  code: "WXYZ-9999",
  generated_by_display_name: "Ada Lovelace",
  org_name: "Acme",
  created_at: "2026-02-01T00:00:00Z",
  revoked_at: null,
};

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

function renderRoute() {
  return render(
    <MemoryRouter>
      <OrganizationRoute />
    </MemoryRouter>,
  );
}

describe("OrganizationRoute (admin)", () => {
  let fetchSpy: MockInstance<typeof fetch>;
  beforeEach(() => {
    fetchSpy = vi.spyOn(globalThis, "fetch");
    vi.stubGlobal("crypto", { randomUUID: () => "idem-1" });
  });
  afterEach(() => {
    fetchSpy.mockRestore();
    vi.unstubAllGlobals();
  });

  it("renders the org (kind=org) card empty state", async () => {
    fetchSpy.mockResolvedValue(jsonResponse({ data: { share_codes: [] } }));
    const { container } = renderRoute();
    await waitFor(() =>
      expect(
        screen.getByText(m.organization_visibility_empty_title()),
      ).toBeInTheDocument(),
    );
    expect(
      container.querySelector('[data-sharecode-kind="org"]'),
    ).toBeInTheDocument();
  });

  it("renders the active code with the generated-by attribution", async () => {
    fetchSpy.mockResolvedValue(jsonResponse({ data: { share_codes: [CODE] } }));
    renderRoute();
    await waitFor(() =>
      expect(
        screen.getByText(
          m.organization_visibility_generated_by({ name: "Ada Lovelace" }),
        ),
      ).toBeInTheDocument(),
    );
    expect(
      screen.getByLabelText(m.organization_visibility_masked_aria_label()),
    ).toBeInTheDocument();
  });

  it("renders every active code and offers a Generate-another action", async () => {
    const CODE_2 = {
      ...CODE,
      id: "sc-2",
      code: "SECOND-CODE",
      generated_by_display_name: "Grace Hopper",
    };
    fetchSpy.mockResolvedValue(
      jsonResponse({ data: { share_codes: [CODE, CODE_2] } }),
    );
    renderRoute();
    await waitFor(() =>
      expect(
        screen.getByText(
          m.organization_visibility_generated_by({ name: "Grace Hopper" }),
        ),
      ).toBeInTheDocument(),
    );
    expect(
      screen.getByText(
        m.organization_visibility_generated_by({ name: "Ada Lovelace" }),
      ),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("button", {
        name: m.organization_visibility_generate_another_cta(),
      }),
    ).toBeInTheDocument();
    expect(
      screen.getAllByRole("button", {
        name: m.organization_visibility_revoke_cta(),
      }),
    ).toHaveLength(2);
  });
});


