/**
 * TenantsRoute tests — covers the route-level modal state machine and
 * the handleDelete child-lookup branch (org vs workspace).
 *
 * NOTE: TenantRowMenu shows mutations when `!isRoot` (workspace rows with
 * parent_id always show Edit/Delete regardless of session tier). We use
 * workspace rows for most mutation-path tests to avoid the session-cache
 * complexity of making org-root rows editable in tests.
 */
import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter } from "react-router-dom";

// ---- Module-level mocks ----

const navigate = vi.fn();

vi.mock("react-router-dom", async () => {
