import type { AdminTenant } from "../../src/api/tenants";

// ─── Fixtures ────────────────────────────────────────────────────────────────

function makeOrg(overrides: Partial<AdminTenant> = {}): AdminTenant {
  return {
    id: "org-1",
    name: "Acme Corp",
    slug: "acme-corp",
    created_at: "2026-01-01T00:00:00Z",
    updated_at: "2026-01-01T00:00:00Z",
    status: "active",
    // No parent_id → org-level
    ...overrides,
  };
}

function makeWorkspace(overrides: Partial<AdminTenant> = {}): AdminTenant {
  return makeOrg({ id: "ws-1", name: "Eng Workspace", slug: "eng", parent_id: "org-1", ...overrides });
}

// ─── Render helper ────────────────────────────────────────────────────────────

function renderRoute(id = "org-1", search = ""): void {
  render(
    <MemoryRouter initialEntries={[`/admin/workspaces/${id}${search}`]}>
      <Routes>
        <Route
          path="/admin/workspaces/:id"
          element={<WorkspaceDetailRoute />}
        />
      </Routes>
    </MemoryRouter>,
  );
}

// ─── Tests ───────────────────────────────────────────────────────────────────

